-- calc_形状_边的类型
-- Field: 形状.边的类型
-- Type: calculated | DataType: string | Returns: TEXT

CREATE OR REPLACE FUNCTION calc_形状_边的类型(p_形状id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_形状_边的数量(p_形状id) AS val) SELECT (CASE WHEN ((SELECT val FROM __erb_dedup_v1))::text = (0)::text THEN '空' WHEN ((SELECT val FROM __erb_dedup_v1))::text = (1)::text THEN '点' WHEN ((SELECT val FROM __erb_dedup_v1))::text = (2)::text THEN '线' WHEN ((SELECT val FROM __erb_dedup_v1))::text = (3)::text THEN '三角形' WHEN ((SELECT val FROM __erb_dedup_v1))::text = (4)::text THEN '正方形' ELSE '--' END)::text;
$$ LANGUAGE sql STABLE;

-- calc_形状_边的数量
-- Field: 形状.边的数量
-- Type: aggregation | DataType: integer | Returns: INTEGER

CREATE OR REPLACE FUNCTION calc_形状_边的数量(p_形状id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM 边 WHERE 形状 = (SELECT NULLIF(形状id, '') FROM 形状 WHERE 形状id = p_形状id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_形状_角度总和
-- Field: 形状.角度总和
-- Type: aggregation | DataType: number | Returns: NUMERIC

CREATE OR REPLACE FUNCTION calc_形状_角度总和(p_形状id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((角度)::numeric), 0) FROM 边 WHERE 形状 = p_形状id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_形状_最大边长
-- Field: 形状.最大边长
-- Type: aggregation | DataType: number | Returns: NUMERIC

CREATE OR REPLACE FUNCTION calc_形状_最大边长(p_形状id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((长度)::numeric), 0) FROM 边 WHERE 形状 = p_形状id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_形状_非斜边角度总和
-- Field: 形状.非斜边角度总和
-- Type: aggregation | DataType: number | Returns: NUMERIC

CREATE OR REPLACE FUNCTION calc_形状_非斜边角度总和(p_形状id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((calc_边_长度平方(边id))::numeric), 0) FROM 边 WHERE 形状 = p_形状id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_形状_勾股定理成立
-- Field: 形状.勾股定理成立
-- Type: calculated | DataType: string | Returns: TEXT

CREATE OR REPLACE FUNCTION calc_形状_勾股定理成立(p_形状id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_形状_最大边长(p_形状id) AS val) SELECT (CASE WHEN (calc_形状_边的数量(p_形状id))::NUMERIC = 3 THEN (calc_形状_非斜边角度总和(p_形状id) = (COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0)))::text ELSE (NULL)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_边_形状的最大边长
-- Field: 边.形状的最大边长
-- Type: lookup | DataType: string | Returns: NUMERIC
-- Lookup: 最大边长 from related 形状

