$$ LANGUAGE sql STABLE;

-- calc_边_名称
-- Field: 边.名称
-- Type: calculated | DataType: string | Returns: TEXT

CREATE OR REPLACE FUNCTION calc_边_名称(p_边id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(形状, '') FROM 边 WHERE 边id = p_边id), '-', (SELECT NULLIF(标签, '') FROM 边 WHERE 边id = p_边id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_边_是否为斜边
-- Field: 边.是否为斜边
-- Type: calculated | DataType: string | Returns: TEXT

CREATE OR REPLACE FUNCTION calc_边_是否为斜边(p_边id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT 长度 FROM 边 WHERE 边id = p_边id) = calc_边_形状的最大边长(p_边id))::text;
$$ LANGUAGE sql STABLE;

-- calc_边_长度平方
-- Field: 边.长度平方
-- Type: calculated | DataType: string | Returns: TEXT

CREATE OR REPLACE FUNCTION calc_边_长度平方(p_边id TEXT)
RETURNS TEXT AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT 长度 FROM 边 WHERE 边id = p_边id)) AS v) __safe_numeric), 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT 长度 FROM 边 WHERE 边id = p_边id)) AS v) __safe_numeric), 0)))::text;
$$ LANGUAGE sql STABLE;

-- ============================================================================
-- MANY-SIDE RELATIONSHIP FUNCTIONS
-- These functions aggregate child records for many-side relationships
-- ============================================================================

-- calc_形状_edges
-- Field: 形状.Edges
-- Type: Many-side relationship (backref) to 边
-- Aggregates: 边.边Id where 形状 = parent
CREATE OR REPLACE FUNCTION calc_形状_edges(p_形状id TEXT)
RETURNS TEXT AS $$
  SELECT (
    SELECT STRING_AGG(边id::TEXT, ', ' ORDER BY 边id)
    FROM 边
    WHERE 形状 = p_形状id
  );
$$ LANGUAGE sql STABLE;

