-- ----------------------------------------------------------------------------
-- vw_形状: Table: 形状
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_形状 CASCADE;
CREATE VIEW vw_形状 WITH (security_invoker = ON) AS
SELECT
  t.形状id,
  t.名称,
  calc_形状_edges(t.形状id) AS edges,
  calc_形状_边的类型(t.形状id) AS 边的类型,
  calc_形状_边的数量(t.形状id) AS 边的数量,
  calc_形状_角度总和(t.形状id) AS 角度总和,
  calc_形状_最大边长(t.形状id) AS 最大边长,
  calc_形状_非斜边角度总和(t.形状id) AS 非斜边角度总和,
  calc_形状_勾股定理成立(t.形状id) AS 勾股定理成立
FROM 形状 t;

-- ----------------------------------------------------------------------------
-- vw_边: Table: 边
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_边 CASCADE;
CREATE VIEW vw_边 WITH (security_invoker = ON) AS
SELECT
  t.边id,
  calc_边_名称(t.边id) AS 名称,
  t.形状,
  calc_边_形状的最大边长(t.边id) AS 形状的最大边长,
  calc_边_边的数量(t.边id) AS 边的数量,
  calc_边_是否为斜边(t.边id) AS 是否为斜边,
  calc_边_形状类型(t.边id) AS 形状类型,
  t.标签,
  t.长度,
  calc_边_长度平方(t.边id) AS 长度平方,
  t.角度
FROM 边 t;



